=== pdi/src/extrairTexto.js
import { getDocument } from 'pdfjs-dist/legacy/build/pdf.mjs'

export async function extrairTexto(bufferPdf) {
  try {
    const documento = await getDocument({
      data: new Uint8Array(bufferPdf),
      useWorkerFetch: false,
      isEvalSupported: false,
    }).promise

    let texto = ''
    for (let i = 1; i <= documento.numPages; i++) {
      const pagina = await documento.getPage(i)
      const conteudo = await pagina.getTextContent()
      texto += conteudo.items.map((item) => item.str).join(' ') + '\n'
    }
    return texto
  } catch {
    return ''
  }
}
=== pdi/src/featherlessClient.js
const ENDPOINT = 'https://api.featherless.ai/v1/chat/completions'

export async function chamarFeatherless(mensagens, opcoes = {}) {
  const {
    fetchImpl = fetch,
    apiKey = process.env.FEATHERLESS_API_KEY,
    modelo = process.env.FEATHERLESS_MODEL || 'deepseek-ai/DeepSeek-V3-0324',
    timeoutMs = 60000,
  } = opcoes

  if (!apiKey) {
    throw new Error('FEATHERLESS_API_KEY não foi fornecida')
  }

  const resposta = await fetchImpl(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({ model: modelo, messages: mensagens }),
    signal: AbortSignal.timeout(timeoutMs),
  })

  if (!resposta.ok) {
    throw new Error(`Featherless respondeu com status ${resposta.status}`)
  }

  const dados = await resposta.json()
  return dados.choices[0].message.content
}
=== pdi/src/habilidades.js
export const HABILIDADES = [
  { id: 'reconhecer-emocoes', nome: 'Reconhecer emoções' },
  { id: 'resposta-social', nome: 'Resposta social' },
  { id: 'empatia', nome: 'Empatia' },
  { id: 'causa-efeito-social', nome: 'Causa e efeito social' },
]

export const idsPermitidos = () => HABILIDADES.map((h) => h.id)

export const nomeHabilidade = (id) => HABILIDADES.find((h) => h.id === id)?.nome ?? id
=== pdi/cli.js
import { readFile } from 'node:fs/promises'
import { extrairTexto } from './src/extrairTexto.js'
import { processarPdi } from './src/processarPdi.js'
import { chamarFeatherless } from './src/featherlessClient.js'
import { HABILIDADES } from './src/habilidades.js'

const caminho = process.argv[2]

if (!caminho) {
  console.error('Uso: node cli.js <caminho-do-pdf>')
  process.exit(1)
}

if (!process.env.FEATHERLESS_API_KEY) {
  console.error(
    'FEATHERLESS_API_KEY não encontrada no ambiente.\n' +
      'Crie pdi/.env a partir de pdi/.env.example com sua chave e rode:\n' +
      '  node --env-file=.env cli.js <caminho-do-pdf>',
  )
  process.exit(1)
}

const buffer = await readFile(caminho)
const texto = await extrairTexto(buffer)
const resultado = await processarPdi(texto, HABILIDADES, chamarFeatherless)

console.log(JSON.stringify(resultado, null, 2))
=== pdi/.env.example
FEATHERLESS_API_KEY=
  const idsValidos = new Set(habilidades.map((h) => normalizar(h.id)))

  let dados
  try {
    const mensagens = montarPrompt(texto, habilidades)
    const bruto = await chamarLLM(mensagens)
    dados = extrairJson(bruto)
  } catch (e) {
    console.warn('pdi: falha ao obter/interpretar resposta da LLM:', e.message)
    return respostaVazia('falha-llm')
  }

  const itensBrutos = Array.isArray(dados.itens) ? dados.itens : []
  const idsVistos = new Set()
  const idsValidosOrdenados = []
  for (const item of itensBrutos) {
    const id = normalizar(item?.habilidade)
    if (idsValidos.has(id) && !idsVistos.has(id)) {
      idsVistos.add(id)
      idsValidosOrdenados.push(id)
    }
  }

  if (idsValidosOrdenados.length === 0) {
    return respostaVazia('nenhuma-habilidade-reconhecida')
  }

  const itens = idsValidosOrdenados.map((id) => ({ habilidade: id, nivel: 1 }))

  const porHabilidadeBruto = Array.isArray(dados.resumoPais?.porHabilidade)
    ? dados.resumoPais.porHabilidade
    : []

  const porHabilidade = idsValidosOrdenados.map((id) => {
    const entrada = porHabilidadeBruto.find((p) => normalizar(p?.habilidade) === id)
    return {
      habilidade: id,
      atencao: sanitizarAtencao(entrada?.atencao),
      atividades: sanitizarAtividades(entrada?.atividades),
    }
  })

  const topicos = idsValidosOrdenados.map((id) => nomeHabilidade(id))

  return {
    itens,
    resumoPais: { topicos, porHabilidade, aviso: AVISO },
  }
}

