const CHAVE = 'dopamine-usuario'

export function usuarioSalvo() {
  try {
    return JSON.parse(localStorage.getItem(CHAVE))
  } catch {
    return null
  }
}

export function salvarUsuario(usuario) {
  try {
    if (usuario) localStorage.setItem(CHAVE, JSON.stringify(usuario))
