import { useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { api } from '../api.js'
import { temaPorId } from '../temas.js'
import { montarAtividade, paraServidor } from '../jogos/integracao.js'
import { estiloTema } from './Crianca.jsx'

// Placeholder: enquanto os jogos não estão integrados, simula uma partida
// e envia um resultado no mesmo formato que os jogos vão enviar.
export default function Jogo({ usuario }) {
  const { jogoId } = useParams()
  const navegar = useNavigate()
  const [dados, setDados] = useState(null)
  const [confirmarSaida, setConfirmarSaida] = useState(false)
  const [ganhou, setGanhou] = useState(null)
  const [erro, setErro] = useState('')

  useEffect(() => {
    api(`/alunos/${usuario.aluno_id}`).then(setDados).catch((e) => setErro(e.message))
  }, [usuario.aluno_id])

  const jogo = dados?.jogos.find((j) => j.id === jogoId)
  const tema = temaPorId(dados?.aluno.hiperfoco)

  async function enviar(resultado) {
    try {
      const { xp } = await api(`/alunos/${usuario.aluno_id}/resultados`, { metodo: 'POST', corpo: paraServidor(jogo, resultado) })
      return xp
    } catch (e) {
      setErro(e.message)
      return null
    }
  }

  async function terminar() {
    const xp = await enviar({ status: 'completed', attempts: 4, correct: 3, hints: 1 })
    if (xp !== null) setGanhou(xp)
  }

  async function sair() {
    await enviar({ status: 'abandoned', attempts: 0, correct: 0, hints: 0 })
    navegar('/crianca')
  }

  if (dados && !jogo) {
    return (
      <div className="crianca" style={estiloTema(tema)}>
        <section className="crianca-bloco">
          <p>Este jogo não está disponível.</p>
          <button onClick={() => navegar('/crianca')}>Voltar</button>
        </section>
      </div>
    )
  }

  return (
    <div className="crianca" style={estiloTema(tema)}>
      <header className="crianca-topo">
        <button onClick={() => (ganhou === null ? setConfirmarSaida(true) : navegar('/crianca'))}>Sair</button>
      </header>

      {erro && <p className="erro" role="alert">{erro}</p>}

      {jogo && ganhou === null && (
        <section className="crianca-bloco jogo-area">
          <span className="emoji grande" aria-hidden="true">{tema?.personagem ?? '🎮'}</span>
          <h1>{jogo.nome}</h1>
          <p className="ajuda">O jogo de verdade vai aparecer aqui (atividade “{montarAtividade({ alunoId: usuario.aluno_id, jogo, tema }).gameId}”).</p>
          <button className="primario grande" onClick={terminar}>Terminar partida (simulação)</button>
        </section>
      )}

      {ganhou !== null && (
        <section className="crianca-bloco jogo-area">
          <span className="emoji grande" aria-hidden="true">⭐</span>
          <h1>Muito bem!</h1>
          <p>Você ganhou XP. Agora tem {ganhou} XP.</p>
          <button className="primario grande" onClick={() => navegar('/crianca')}>Voltar aos jogos</button>
        </section>
      )}

      {confirmarSaida && (
        <div className="fundo-dialogo">
          <div className="dialogo" role="dialog" aria-modal="true" aria-labelledby="titulo-sair">
            <p id="titulo-sair">Quer sair do jogo?</p>
            <div className="linha centro">
              <button className="primario" onClick={() => setConfirmarSaida(false)}>Continuar jogando</button>
              <button onClick={sair}>Sair</button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

// Ponto único de integração entre o site e os jogos (raiz do repo, src/games/).
// O formato ainda vai ser combinado com quem faz os jogos. Por enquanto seguimos
// src/core/contracts.js: o site monta uma activity e recebe um resultado como o de createResult().

export function montarAtividade({ alunoId, jogo, tema }) {
  return {
    activityId: `${alunoId}-${jogo.id}-${Date.now()}`,
    gameId: jogo.game_id,
    theme: tema?.id ?? 'neutro',
    images: [], // as imagens por tema ainda vão ser definidas com a equipe dos jogos
  }
}

// Resultado que o site envia ao servidor. `resultado` vem do jogo:
// { status: 'completed' | 'abandoned', attempts, correct, hints }.
export function paraServidor(jogo, resultado) {
  const { status, attempts = 0, correct = 0, hints = 0 } = resultado
  return { jogoId: jogo.id, status, attempts, correct, hints }
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { api } from '../api.js'
import { TEMAS, temaPorId } from '../temas.js'

const XP_POR_ITEM = 20 // igual a site/server/src/regras.js

// Aplica as cores do tema como tokens; a estrutura da tela não muda.
export function estiloTema(tema) {
  return tema ? { '--tema': tema.cor, '--tema-fundo': tema.fundo } : undefined
}

function EscolherTema({ escolher }) {
  return (
    <section className="crianca-bloco">
      <h1>Do que você mais gosta?</h1>
      <div className="grade-temas">
        {TEMAS.map((t) => (
          <button key={t.id} className="tema" style={estiloTema(t)} onClick={() => escolher(t.id)}>
            <span className="emoji" aria-hidden="true">{t.personagem}</span>
            {t.nome}
          </button>
        ))}
      </div>
    </section>
  )
}

export default function Crianca({ usuario, sair }) {
  const [dados, setDados] = useState(null)
  const [trocando, setTrocando] = useState(false)
  const [erro, setErro] = useState('')
  const navegar = useNavigate()

  useEffect(() => {
    api(`/alunos/${usuario.aluno_id}`).then(setDados).catch((e) => setErro(e.message))
  }, [usuario.aluno_id])

  async function escolher(hiperfoco) {
    const aluno = await api(`/alunos/${usuario.aluno_id}/hiperfoco`, { metodo: 'PATCH', corpo: { hiperfoco } })
    setDados((d) => ({ ...d, aluno }))
    setTrocando(false)
  }

  const tema = temaPorId(dados?.aluno.hiperfoco)
  const desbloqueados = tema ? Math.min(Math.floor((dados.xp ?? 0) / XP_POR_ITEM), tema.itens.length) : 0
  const progresso = ((dados?.xp ?? 0) % XP_POR_ITEM) / XP_POR_ITEM

  return (
    <div className="crianca" style={estiloTema(tema)}>
      <header className="crianca-topo">
        <button onClick={sair}>Sair</button>
        {tema && !trocando && <button onClick={() => setTrocando(true)}>Trocar tema</button>}
      </header>

      {erro && <p className="erro" role="alert">{erro}</p>}

      {dados && (!tema || trocando) && <EscolherTema escolher={escolher} />}

      {dados && tema && !trocando && (
        <>
          <section className="crianca-bloco avatar">
            <span className="emoji grande" aria-hidden="true">{tema.personagem}</span>
            <div>
              <h1>Oi, {dados.aluno.nome}!</h1>
              <div className="xp" role="progressbar" aria-valuemin={0} aria-valuemax={XP_POR_ITEM} aria-valuenow={dados.xp % XP_POR_ITEM} aria-label="XP até o próximo item">
                <span style={{ width: `${progresso * 100}%` }} />
              </div>
              <p>⭐ {dados.xp} XP</p>
            </div>
          </section>

          <section className="crianca-bloco">
            <h2>🎮 Seus jogos</h2>
            {dados.jogos.length ? (
              <div className="grade-jogos">
                {dados.jogos.map((j) => (
                  <button key={j.id} className="cartao-jogo" onClick={() => navegar(`/crianca/jogo/${j.id}`)}>
                    <span className="emoji" aria-hidden="true">▶️</span>
                    {j.nome}
                  </button>
                ))}
              </div>
            ) : (
              <p>Logo seus jogos vão aparecer aqui. 🙂</p>
            )}
          </section>

          <section className="crianca-bloco">
            <h2>🏆 Sua coleção</h2>
            <ul className="colecao">
              {tema.itens.map((item, i) => (
                <li key={item} className={i < desbloqueados ? 'ganho' : 'bloqueado'} aria-label={i < desbloqueados ? 'Item ganho' : 'Item ainda não ganho'}>
                  {i < desbloqueados ? item : '?'}
                </li>
              ))}
            </ul>
          </section>
        </>
      )}
    </div>
  )
}

