p='estilo.css'; s=open(p).read()
old_tokens = s[s.index(':root {'):s.index('  font-family: \'Atkinson\'')]
new_tokens = """:root {
  /* Marca Gump: verde esmeralda + rosa rubi + pêssego sobre creme rosado. */
  --verde: #2E9E6B;
  --verde-forte: #1F7A50;
  --verde-claro: #DFF2E7;
  --rubi: #D9406E;
  --rubi-forte: #B8325A;
  --pessego: #FF9F6B;
  --pessego-claro: #FFE6D6;
  --papel: #FFF6F0;
  --cartao: #ffffff;
  --tinta: #1E3B2F;
  --suave: #55665D;
  --ok: var(--verde-forte);
  --alerta: #9A4A12;
  --erro: #A8324F;
  --borda: #EADBD0;
  --tema: var(--verde);
  --tema-fundo: var(--verde-claro);
"""
s = s.replace(old_tokens, new_tokens)
old_login = s[s.index('/* Login */'):s.index('/* Áreas de adulto */')]
new_login = """/* Login: metade com a marca, metade com o formulário. */
.login { min-height: 100dvh; display: grid; grid-template-columns: 1fr 1fr; }
.login-marca { position: relative; overflow: hidden; background: var(--verde-claro); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 24px; padding: 48px 32px; text-align: center; }
.login-marca .logo, .login-frase { position: relative; }
.login-frase { margin: 0; max-width: 22ch; font-family: 'Fredoka', 'Atkinson', sans-serif; font-weight: 600; font-size: 1.7rem; line-height: 1.25; color: var(--tinta); }
.bolha { position: absolute; border-radius: 50%; }
.bolha.b1 { width: 340px; height: 340px; background: var(--pessego-claro); top: -110px; left: -120px; }
.bolha.b2 { width: 220px; height: 220px; background: #F6C9D6; bottom: -60px; right: -50px; }
.bolha.b3 { width: 90px; height: 90px; background: var(--pessego); bottom: 22%; left: 12%; opacity: 0.55; }
.login-form { display: grid; place-items: center; padding: 32px 16px; background: var(--papel); }
.login-form form { width: min(400px, 100%); display: flex; flex-direction: column; gap: 16px; }
.login-form h1 { font-family: 'Fredoka', 'Atkinson', sans-serif; font-size: 2rem; color: var(--tinta); }
.demo { border-top: 1px solid var(--borda); padding-top: 14px; }
.demo p { margin: 0 0 10px; color: var(--suave); }
.demo-botoes { display: flex; gap: 8px; flex-wrap: wrap; }
.demo-botoes button { border: none; flex: 1; }
.demo-verde { background: var(--verde-claro); color: var(--verde-forte); }
.demo-rubi { background: #FBE1E9; color: var(--rubi-forte); }
.demo-pessego { background: var(--pessego-claro); color: var(--alerta); }

"""
s = s.replace(old_login, new_login)
s = s.replace(".marca { margin: 0; font-weight: 700; color: var(--ok); letter-spacing: 0.02em; }\n", "")
s = s.replace("button.primario { background: var(--tinta); color: var(--cartao); }", "button.primario { background: var(--verde-forte); border-color: var(--verde-forte); color: #fff; }\nbutton.primario:hover:not(:disabled) { background: var(--tinta); border-color: var(--tinta); }")
s = s.replace("@media (max-width: 600px) {\n", "@media (max-width: 760px) {\n  .login { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }\n  .login-marca { padding: 32px 16px; gap: 12px; }\n  .login-marca .logo { font-size: 48px !important; }\n  .login-frase { font-size: 1.25rem; }\n}\n\n@media (max-width: 600px) {\n")
open(p,'w').write(s)
EOF
