  const feitos = [Boolean(pdi && !pdi.erro), Boolean(pdi?.itens.length), jogos.length > 0 && pendentes.length === 0]

  return (
    <div className="adulto">
      <Cabecalho usuario={usuario} sair={sair} titulo="Escola">
        <label className="seletor-aluno">
